import itertools
from collections import defaultdict, deque


def poker_hands(cards, hand_size):
    return list(itertools.combinations(cards, hand_size))


class _BoundedHistory:
    def __init__(self, maxsize):
        self._history = deque(maxlen=maxsize)

    def append(self, item):
        self._history.append(item)

    def items(self):
        return list(self._history)


def bounded_history(maxsize):
    return _BoundedHistory(maxsize)


def multidict_merge(*dicts):
    result = defaultdict(list)
    for key, value in itertools.chain.from_iterable(d.items() for d in dicts):
        result[key].append(value)
    return dict(result)
